import os

import pytest

from pages.login_generated_page import LoginGeneratedPage

pytestmark = [pytest.mark.ui]


@pytest.mark.smoke
@pytest.mark.login
def test_tc_001_valid_login(page, base_url, runtime_options) -> None:
    """Valid login

    ID: TC-001 | Priority: High | Source: login.csv

    Preconditions:
      - User exists

    Expected:
      - User is redirected to the inventory page
    """
    page_obj = LoginGeneratedPage(page, runtime_options["resilience_policy"])
    # Step 1: Navigate to /login
    page_obj.open(base_url, '/login')
    # Step 2: Enter valid username
    page_obj.enter_username(os.environ.get("INNOHARMONY_TEST_USERNAME", ""))
    # Step 3: Enter valid password
    page_obj.enter_password(os.environ.get("INNOHARMONY_TEST_PASSWORD", ""))
    # Step 4: Click the Login button
    page_obj.click_login_button()
    # Expected: User is redirected to the inventory page
    # NOTE: confirm 'inventory' is part of the target page URL
    page_obj.wait_for_url_contains('inventory')


@pytest.mark.negative
@pytest.mark.regression
def test_tc_002_invalid_login_shows_error(page, base_url, runtime_options) -> None:
    """Invalid login shows error

    ID: TC-002 | Priority: Medium | Source: login.csv

    Expected:
      - Error message "Epic sadface" is displayed
    """
    page_obj = LoginGeneratedPage(page, runtime_options["resilience_policy"])
    # Step 1: Open the login page
    page_obj.open(base_url)
    # Step 2: Enter "bad_user" in the username field
    page_obj.enter_username('bad_user')
    # Step 3: Type password as wrong
    page_obj.enter_password('invalid-password')
    # Step 4: Click Login
    page_obj.click_login_button()
    # Expected: Error message "Epic sadface" is displayed
    assert 'Epic sadface' in page_obj.get_error_message_text()


